\"轮班不固定，每周学习时间待确定；暂不设完成日期，按实际投入调整节奏。\",\"unresolved\":[]},\"status\":\"ok\"}},{\"input\":{\"currentQuestion\":\"time\",\"locale\":\"zh-CN\",\"messages\":[{\"ref\":\"U1\",\"role\":\"user\",\"text\":\"一周大概两小时。\"}],\"questionIds\":[\"goal\",\"purpose\",\"baseline\",\"time\"]},\"response\":{\"missing\":[],\"reply\":\"每周大概能学两小时。是否确认该回答？\",\"result\":{\"complete\":true,\"consistency\":{\"issues\":[],\"status\":\"consistent\"},\"evidence\":[{\"field\":\"weekly\",\"messageRef\":\"U1\",\"proposalRef\":null,\"quote\":\"用户给出了每周可用时间。\"}],\"fields\":{\"weekly\":\"每周约两小时\"},\"questionId\":\"time\",\"summary\":\"每周大概能学两小时。\",\"unresolved\":[]},\"status\":\"ok\"}}]\n\nOUTPUT_SCHEMA:\n{\"$defs\":{\"assistantRef\":{\"pattern\":\"^A[1-9][0-9]{0,3}$\",\"type\":\"string\"},\"consistencyAssessment\":{\"additionalProperties\":false,\"allOf\":[{\"if\":{\"properties\":{\"status\":{\"const\":\"consistent\"}}},\"then\":{\"properties\":{\"issues\":{\"maxItems\":0}}}},{\"if\":{\"properties\":{\"status\":{\"const\":\"requires_review\"}}},\"then\":{\"properties\":{\"issues\":{\"minItems\":1}}}}],\"properties\":{\"issues\":{\"items\":{\"$ref\":\"#/$defs/consistencyIssue\"},\"maxItems\":7,\"minItems\":0,\"type\":\"array\"},\"status\":{\"enum\":[\"consistent\",\"requires_review\"]}},\"required\":[\"status\",\"issues\"],\"type\":\"object\"},\"consistencyIssue\":{\"additionalProperties\":false,\"allOf\":[{\"if\":{\"properties\":{\"questionId\":{\"const\":\"goal\"}}},\"then\":{\"properties\":{\"fields\":{\"items\":{\"enum\":[\"topic\",\"outcome\"]}},\"suggestion\":{\"properties\":{\"fields\":{\"propertyNames\":{\"enum\":[\"topic\",\"outcome\"]}}}}}}},{\"if\":{\"properties\":{\"questionId\":{\"const\":\"purpose\"}}},\"then\":{\"properties\":{\"fields\":{\"items\":{\"enum\":[\"context\",\"criteria\",\"aids\"]}},\"suggestion\":{\"properties\":{\"fields\":{\"propertyNames\":{\"enum\":[\"context\",\"criteria\",\"aids\"]}}}}}}},{\"if\":{\"properties\":{\"questionId\":{\"const\":\"baseline\"}}},\"then\":{\"pr